def a(i,d,s,what,why,b='raw:guix/unowned-groups.json'):
 i='guix-'+i
 if i not in seen:w.writerow([i,d,s,what,b,why]);f.flush();seen.add(i)
def m(i,what,why,b='raw:guix/unowned-groups.json',s='S2.2-1,S2.2-2'):a(i,'MUST',s,what,why,b)
def n(i,what,why,b='raw:guix/unowned-groups.json',s='S2.2-7,S2.2-13'):a(i,'NOT',s,what,why,b)
def u(i,what,why):a(i,'UNKNOWN','S3-1,S3-2',what,why)
def doc(x):return 'doc:https://man7.org/linux/man-pages/man5/'+x+'.5.html'
